92	    }
93	    const hit = usable.find((item) => namesMatch(name, item.normalizedName));
94	    if (!hit) {
95	      return { ingredientIndex, status: 'missing', pantryItemId: null, pantryItemName: null, daysToExpiry: null };
96	    }
97	    const status = hasEnough(ing, hit) ? 'have' : 'insufficient';
98	    return {
99	      ingredientIndex,
100	      status,
101	      pantryItemId: hit.id,
102	      pantryItemName: hit.name,
103	      daysToExpiry: hit.daysToExpiry,
104	    };
105	  });
106	}
