1	import 'server-only';
2	import { normalizeIngredientName } from '@/server/recipes/parse';
3	
4	// SPEC F5: pantry_items.normalized_name is computed server-side and must match the
5	// normalizedName that recipe matching computes for ingredient lines. So pantry names go
6	// through the SAME function as recipe ingredients (Hang's normalizeIngredientName, read-only),
7	// after stripping the two things only product names have:
8	//   - the product's brand (each comma-separated phrase of `brand`, as whole words)
9	//   - package-size text ("400 g", "2 x 500 ml", "12 ct", the EU estimated sign "e"/"℮")
10	// Team decision 2026-11-08: no marketing-adjective stripping.
11	
12	const BOUNDARY_START = '(?<![\\p{L}\\p{N}])';
13	const BOUNDARY_END = '(?![\\p{L}\\p{N}])';
14	const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
15	
16	const SIZE_UNIT = '(?:kg|g|mg|ml|cl|dl|l|fl\\.?\\s*oz|oz|lbs?|ct|pcs|pc|pk|pack|count)';
17	const NUM = '\\d+(?:[.,]\\d+)?';
18	const PACKAGE_SIZE_RE = new RegExp(
19	  `${BOUNDARY_START}${NUM}\\s*(?:x\\s*${NUM}\\s*)?${SIZE_UNIT}\\.?(?:\\s*(?:e|℮)${BOUNDARY_END})?${BOUNDARY_END}`,
20	  'giu',
21	);
22	
23	/** Removes brand phrases and package sizes from a product name. Never returns undefined; may return ''. */
24	export function stripBrandAndSize(name: string, brand?: string | null): string {
25	  let s = name.replace(/℮/g, ' ');
26	  for (const phrase of (brand ?? '').split(',').map((b) => b.trim()).filter(Boolean)) {
27	    s = s.replace(new RegExp(`${BOUNDARY_START}${escapeRe(phrase)}(?:'s)?${BOUNDARY_END}`, 'giu'), ' ');
28	  }
29	  s = s.replace(PACKAGE_SIZE_RE, ' ');
30	  return s.replace(/\s+/g, ' ').trim();
31	}
32	
33	/**
34	 * normalized_name for a pantry item: brand and size stripped, then recipe normalization
35	 * (lowercase, descriptors like fresh/chopped removed, naive singular).
36	 * Falls back to normalizing the full name when stripping leaves nothing ("Nutella" by Nutella).
37	 */
38	export function normalizePantryName(name: string, brand?: string | null): string {
39	  const stripped = normalizeIngredientName(stripBrandAndSize(name, brand));
40	  if (stripped) return stripped;
41	  const full = normalizeIngredientName(name);
42	  return full || name.trim().toLowerCase();
43	}
