1	import type { PantryMatch, RecipeIngredient, RecipeScore } from '@/contracts/domain';
2	
3	export interface ScorableCandidate {
4	  ingredients: RecipeIngredient[];
5	  matches: PantryMatch[];
6	  proteinPerServingG: number | null;
7	}
8	
9	/**
10	 * Deterministic ranking (§9 F6):
11	 *   coverage    = matched non-staple / total non-staple (have + insufficient count)
12	 *   w(d)        = 1 / (1 + max(d, 0))
13	 *   expiryScore = Σw / (Σw + 1) over matched items
14	 *   proteinNorm = min(proteinPerServingG / 40, 1) iff high_protein, else 0
15	 *   score       = 0.5·coverage + 0.35·expiryScore + 0.15·proteinNorm − 0.1·missingCount
16	 *
17	 * Note: the SPEC sketches cross-set normalization for expiryScore, but search
18	 * must stream each candidate with its FINAL score as it finishes (F6 step 8),
19	 * which a set-dependent normalization forbids. The saturating Σw/(Σw+1) form
20	 * preserves the ordering intent (more/sooner-expiring matches → higher) while
21	 * staying per-candidate computable. The SPEC explicitly allows tuning.
22	 */
23	export function computeScores(candidates: ScorableCandidate[], opts: { highProtein: boolean }): RecipeScore[] {
24	  return candidates.map((c) => {
25	    const sum = expirySum(c.matches);
26	    const nonStaple = c.ingredients.filter((ing) => !ing.isStaple);
27	    const nonStapleIdx = new Set(
28	      c.ingredients.map((ing, idx) => ({ ing, idx })).filter(({ ing }) => !ing.isStaple).map(({ idx }) => idx),
29	    );
30	    const relevant = c.matches.filter((m) => nonStapleIdx.has(m.ingredientIndex));
31	    const matched = relevant.filter((m) => m.status === 'have' || m.status === 'insufficient').length;
32	    const missingCount = relevant.filter((m) => m.status === 'missing').length;
33	
34	    const coverage = nonStaple.length === 0 ? 1 : matched / nonStaple.length;
35	    const expiryScore = sum > 0 ? sum / (sum + 1) : 0;
36	    const proteinNorm =
37	      opts.highProtein && c.proteinPerServingG != null ? Math.min(c.proteinPerServingG / 40, 1) : 0;
38	    const score = 0.5 * coverage + 0.35 * expiryScore + 0.15 * proteinNorm - 0.1 * missingCount;
39	
40	    return {
41	      coverage,
42	      expiryScore,
43	      missingCount,
44	      proteinPerServingG: c.proteinPerServingG,
45	      score: Math.round(score * 1000) / 1000,
46	    };
47	  });
48	}
49	
50	function expirySum(matches: PantryMatch[]): number {
51	  let sum = 0;
52	  for (const m of matches) {
53	    if ((m.status === 'have' || m.status === 'insufficient') && m.daysToExpiry != null) {
54	      sum += 1 / (1 + Math.max(m.daysToExpiry, 0));
55	    }
56	  }
57	  return sum;
58	}
