1	import 'server-only';
2	import { GoogleGenAI, type Part } from '@google/genai';
3	import type { ZodType } from 'zod';
4	import { getEnv } from '../env';
5	
6	let client: GoogleGenAI | null = null;
7	
8	function getClient(): GoogleGenAI {
9	  // Vertex AI via Application Default Credentials (`gcloud auth application-default login` locally).
10	  if (!client) {
11	    const env = getEnv();
12	    client = new GoogleGenAI({ vertexai: true, project: env.GOOGLE_CLOUD_PROJECT, location: env.GOOGLE_CLOUD_LOCATION });
13	  }
14	  return client;
15	}
16	
17	export interface GeminiImage {
18	  mimeType: 'image/jpeg' | 'image/png' | 'image/webp' | 'image/heic' | 'image/heif';
19	  base64: string;
20	}
21	
22	async function callWithTimeout<T>(fn: (signal: AbortSignal) => Promise<T>, timeoutMs: number): Promise<T> {
23	  const controller = new AbortController();
24	  const timer = setTimeout(() => controller.abort(), timeoutMs);
25	  try {
26	    return await fn(controller.signal);
27	  } finally {
28	    clearTimeout(timer);
29	  }
30	}
31	
32	function stripJsonFences(text: string): string {
33	  return text
34	    .trim()
35	    .replace(/^```(?:json)?\s*/i, '')
36	    .replace(/```\s*$/, '')
37	    .trim();
38	}
39	
40	function tryParseJson(text: string): unknown {
41	  try {
42	    return JSON.parse(text);
43	  } catch {
44	    return undefined;
45	  }
46	}
47	
48	/**
49	 * JSON-mode call, NO tools (§10.3.1). Validates with zod; strips ```json
50	 * fences; 1 retry if the response doesn't parse or doesn't match `zod` —
51	 * structured output guarantees schema-shaped JSON, not correct values
52	 * (https://ai.google.dev/gemini-api/docs/structured-output), so callers must
53	 * still sanity-check the data.
54	 */
55	export async function geminiJson<T>(opts: {
56	  system?: string;
57	  text: string; // put the text prompt BEFORE images (docs tip)
58	  images?: GeminiImage[];
59	  jsonSchema: object; // Gemini JSON-Schema subset (§10.3.6)
60	  zod: ZodType<T>;
61	  model?: string;
62	  timeoutMs?: number;
63	}): Promise<{ data: T; model: string }> {
64	  const env = getEnv();
65	  const model = opts.model ?? env.GEMINI_MODEL;
66	  const timeoutMs = opts.timeoutMs ?? 30_000;
67	
68	  const parts: Part[] = [{ text: opts.text }];
69	  for (const image of opts.images ?? []) {
70	    parts.push({ inlineData: { mimeType: image.mimeType, data: image.base64 } });
71	  }
72	
73	  const attempt = async () => {
74	    const response = await callWithTimeout(
75	      (signal) =>
76	        getClient().models.generateContent({
77	          model,
78	          contents: [{ role: 'user', parts }],
79	          config: {
80	            systemInstruction: opts.system,
81	            responseMimeType: 'application/json',
82	            responseSchema: opts.jsonSchema,
83	            abortSignal: signal,
84	          },
85	        }),
86	      timeoutMs,
